<?php require_once __DIR__.'/bootstrap.php'; if(current_user()){header('Location: index.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim((string)($_POST['email']??'')));$pw=(string)($_POST['password']??'');$s=$pdo->prepare('SELECT id,name,email,password_hash,role FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($pw,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];header('Location: '.($u['role']==='admin'?'admin.php':'index.php'));exit;}$error='Email or password is incorrect.';} page_start('Sign in'); ?>
<div class="panel" style="max-width:520px;margin:auto"><h1>Welcome back</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Email</label><input type="email" name="email" required autocomplete="email"><label>Password</label><input type="password" name="password" required autocomplete="current-password"><button>Sign in</button></form><p>New here? <a href="register.php">Create an account</a></p></div><?php page_end(); ?>
